<script setup lang="ts">
import {computed,onMounted,ref} from 'vue'; import {Search,Users} from 'lucide-vue-next'; import {getClassChildren,getTeacherClasses} from '../api/teacher'; import type {Child} from '../types/api';
type Row=Child&{className:string}; const rows=ref<Row[]>([]),query=ref(''),loading=ref(true),error=ref('');
const filtered=computed(()=>rows.value.filter(x=>`${x.full_name} ${x.saint_name} ${x.code}`.toLowerCase().includes(query.value.toLowerCase())));
async function load(){loading.value=true;error.value='';try{const classes=(await getTeacherClasses()).data.data;const pages=await Promise.all(classes.map(c=>getClassChildren(c.id)));rows.value=pages.flatMap((r,i)=>r.data.data.map(child=>({...child,className:classes[i].name})));}catch{error.value='Không thể tải danh sách thiếu nhi.';}finally{loading.value=false;}}onMounted(load);
</script>
<template><div><h2 class="text-xl font-bold text-ink">Thiếu nhi</h2><p class="mt-1 text-sm text-slate-500">Danh sách thiếu nhi thuộc các lớp bạn phụ trách.</p><div class="mt-6 overflow-hidden rounded-2xl border border-slate-200 bg-white"><div class="border-b border-slate-100 p-4"><label class="flex max-w-sm items-center gap-2 rounded-xl bg-slate-50 px-3 py-2"><Search class="size-4 text-slate-400"/><input v-model="query" class="w-full bg-transparent text-sm outline-none" placeholder="Tìm theo tên hoặc mã..."></label></div><div v-if="loading" class="p-6 text-sm text-slate-500">Đang tải danh sách…</div><div v-else-if="error" class="p-8 text-center text-rose-700">{{error}} <button class="ml-2 font-semibold text-primary-600" @click="load">Thử lại</button></div><div v-else-if="!filtered.length" class="p-10 text-center"><Users class="mx-auto size-9 text-slate-400"/><p class="mt-3 text-slate-500">Không có thiếu nhi phù hợp.</p></div><div v-else><div v-for="student in filtered" :key="`${student.id}-${student.className}`" class="flex items-center gap-3 border-b border-slate-100 p-4 last:border-0"><span class="grid size-10 place-items-center rounded-full bg-primary-100 text-sm font-semibold text-primary-700">{{student.full_name.split(' ').slice(-2).map(x=>x[0]).join('')}}</span><div class="flex-1"><p class="font-medium text-ink">{{student.full_name}}</p><p class="text-xs text-slate-500">{{student.code}} · {{student.saint_name||'Chưa cập nhật tên thánh'}} · {{student.className}}</p></div><span class="rounded-full bg-emerald-50 px-2.5 py-1 text-xs text-emerald-700">Đang học</span></div></div></div></div></template>
